 FieldBirdRuntime runtime;SourceRandom rng(19),reference(19);uint32_t skin=reference.randi()%data.rules().skin_mod;reference.randf();reference.randi();reference.randi();unsigned textures=0,finished=0,timeouts=0;std::function<bool(FieldBirdClipRole)>finish;
