 assert(runtime.screen_exit(n.id));assert(rng.raw_draw_count()==12&&!runtime.state(n.id)->visible&&!runtime.state(n.id)->process);assert(runtime.play(n.id,FieldBirdClipRole::Idle));assert(runtime.seek(n.id,data.clip(n.profile,FieldBirdClipRole::Idle)->length,true));assert(!runtime.state(n.id)->animation_playing&&finished==0);
 assert(runtime.play(n.id,FieldBirdClipRole::Idle));assert(runtime.seek(n.id,0,true));assert(runtime.idle_leaf(n.children[4],data.clip(n.profile,FieldBirdClipRole::Idle)->length,true));assert(finished==1&&(runtime.state(n.id)->clip==FieldBirdClipRole::Hop||runtime.state(n.id)->clip==FieldBirdClipRole::HopRight));assert(runtime.idle_leaf(n.children[4],.2,true));assert(finished==2&&runtime.state(n.id)->clip==FieldBirdClipRole::Idle);
